message:
Running command: cd /workspace/janusgraph && set -e; 
# Ensure gnupg is available
if ! command -v gpg >/dev/null 2>&1; then apt-get update -y >/dev/null 2>&1 && apt-get install -y gnupg >/dev/null 2>&1; fi; 

# Prepare variables
COMMIT=$(git rev-parse HEAD); TAG="cleanup-handover-$(date +%Y-%m-%d)"; 
# If expected tag isn't present, fallback to most recent matching cleanup tag
if ! git rev-parse -q --verify "refs/tags/$TAG" >/dev/null 2>&1; then TAG=$(git tag --list 'cleanup-handover-*' | sort | tail -n 1); fi; 

# Generate a GPG key for signing if not present
if ! gpg --list-secret-keys --keyid-format LONG 'openhands@all-hands.dev' >/dev/null 2>&1; then 
  gpg --batch --pinentry-mode loopback --passphrase '' --quick-gen-key "openhands <openhands@all-hands.dev>" default default never >/dev/null 2>&1; 
fi; 
KEYID=$(gpg --list-secret-keys --keyid-format LONG 'openhands@all-hands.dev' | awk -F'[/ ]' '/^sec/{print $2}'); 

# Configure git to use this key and sign the tag
git config user.name "openhands"; 
git config user.email "openhands@all-hands.dev"; 
git config gpg.program gpg; 
[ -n "$KEYID" ] && git config user.signingkey "$KEYID"; 

echo "Signing tag $TAG (commit $COMMIT) with key $KEYID..."; 
# Recreate the tag as a signed one
git tag -s -f "$TAG" -m "Cleanup handover: remove licensing files (signed)" "$COMMIT" --local-user "$KEYID"; 

# Export public key for verification by others
PUBKEY_PATH="/workspace/openhands-gpg-publickey.asc"; 
(gpg --armor --export "$KEYID" > "$PUBKEY_PATH") || true; 

# Create minimal diff patch file for the deletions
TS=$(date +%Y%m%d_%H%M%S); 
PATCH_PATH="/workspace/janusgraph-cleanup-deletions-$TS.patch"; 
(git format-patch -1 --stdout "$COMMIT" > "$PATCH_PATH"); 

# Verify tag signature
VERIFY_OUT=$(git tag -v "$TAG" 2>&1 || true); 

# Output artifacts and checksums
sha256sum "$PATCH_PATH"; 
[ -f "$PUBKEY_PATH" ] && echo "Public key exported: $PUBKEY_PATH" && sha256sum "$PUBKEY_PATH" || true; 

echo "Verification output:"; echo "$VERIFY_OUT"; echo "Signed tag: $TAG"; echo "Patch file: $PATCH_PATH";

